SELECT 

    AND i.factory = #{factory}
    AND i.category_l1_id = #{categoryL1Id}
    AND i.category_l2_id = #{categoryL2Id}
    AND i.status = #{status}
    AND i.submit_time >= #{startTime}
    AND i.submit_time <= #{endTime}

ORDER BY i.submit_time DESC, i.id DESC
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(1)
FROM cps_issue i

    AND i.factory = #{factory}
    AND i.category_l1_id = #{categoryL1Id}
    AND i.category_l2_id = #{categoryL2Id}
    AND i.status = #{status}
    AND i.submit_time >= #{startTime}
    AND i.submit_time <= #{endTime}
